export const tableLayout = (variant = 'default') => `
<div class="datatable" id="datatable">
  <div class="datatable_header">
    <div class="datatable_title" id="datatable-title"><h1>${variant === 'photos' ? 'Reconocimiento Facial / Guardias' : 'Guardias'}</h1></div>
    <div class="datatable_tools" id="datatable-tools">
      <div class="form_input">
      <label class="form_label" for="search-type-user">Mostrar guardia</label>
      <select class="input_time input_time-start" id="search-type-user">
          <option value="THIS" selected>Solo empresa actual</option>
          <option value="ALL">Todas las empresas</option>
      </select>
      </div>
      <input type="search"
      class="search_input"
      placeholder="Buscar"
      id="search">
      <button
          class="datatable_button add_user"
          id="btnSearch">
          <i class="fa-solid fa-search"></i>
      </button>
      ${variant === 'photos' ? '' : `
      <button
        class="datatable_button add_user"
        id="new-entity">
        <i class="fa-solid fa-user-plus"></i>
      </button>
      `}

      ${variant === 'photos' ? '' : `
      <button
        class="datatable_button import_user"
        id="import-entities">
        Importar
      </button>

      <button
        class="datatable_button import_user"
        id="assign-guard-entities">
        Asignar
      </button>

      <button class="datatable_button import_user" id="export-entities">Exportar</button>
      `}
    </div>
  </div>

  <table class="datatable_content">
    <thead><tr>
      <th><span data-type="customer">
        Empresa <i class="fa-regular fa-filter"></i>
      </span></th>

      <th><span data-type="name">
        Nombre <i class="fa-regular fa-filter"></i>
      </span></th>

      <th colspan="${variant === 'photos' ? '1' : '2'}"><span data-type="id">
        ID <i class="fa-regular fa-filter"></i>
      </span></th>

      <!-- th class="header_filled header_key"></!-->

      <th class="thead_centered"><span data-type="status">
        Estado <i class="fa-regular fa-filter"></i>
      </span></th>

      <th class="thead_centered"><span data-type="position">
        Puesto <i class="fa-regular fa-filter"></i>
      </span></th>

      <!-- <th><span data-type="citadel">
        Ciudadela <i class="fa-regular fa-filter"></i>
      </span></th> -->

      <th class="header_filled"></th>

    </tr></thead>
    <tbody id="datatable-body" class="datatable_body">

    </tbody>
  </table>

  </div>
  <div class="datatable_footer margin_t_8">
    <div class="datatable_pagination" id="pagination-container"></div>
  </div>`;

export const UIProgress = `
  <div class="dialog_content" id="dialog-progress">
    <div class="dialog">
        <div class="dialog_container padding_8">
            <div class="dialog_header">
                <h2 id="progress-title">Procesando...</h2>
            </div>
            <div class="dialog_message padding_8">
                <div id="progress-container" style="width: 100%; background: #eee; border-radius: 5px; overflow: hidden;">
                    <div id="progress-bar" style="width: 0%; height: 20px; background: #007bff; transition: width 0.3s;"></div>
                </div>
                <p id="progress-text" style="text-align: center; margin-top: 10px;">0%</p>
                <div id="error-container" style="display: none; color: red; margin-top: 10px; border: 1px solid red; padding: 10px; border-radius: 5px; max-height: 150px; overflow-y: scroll; white-space: pre-wrap; font-family: monospace; font-size: 12px; scrollbar-width: thin; scrollbar-color: #f87171 transparent;">
                    <strong>Detalles:</strong><br>
                    <span id="error-message" style="font-weight: bold;"></span>
                    <br><span id="error-cause"></span>
                </div>
            </div>
            <div class="dialog_footer" id="progress-footer" style="display: none;">
                <button class="btn btn_primary" id="close-progress">Cerrar</button>
            </div>
        </div>
    </div>
  </div>
`;

